// === CONFIG — nur hier etwas eintragen ===
const CONFIG = {
  // Zeitraum. Bis-Datum ist EXKLUSIV -> fuer Januar 2026: 2026-01-01 / 2026-02-01
  VON: '2026-01-01',
  BIS: '2026-02-01',

  // Shop in JTL. 3 = BB / Zauberbuechse
  K_SHOP: 3,

  // Nummernfeld. 'cInetBestellNr' = Shopify-Bestellnummer
  NUMMERN_FELD: 'cInetBestellNr',

  // Trennzeichen fuer die Matrixify-Filterliste
  TRENNER: ', '
};

// Monatslabel fuer Dateinamen: 2026-01
const label = String(CONFIG.VON).slice(0, 7);

return [{ json: { cfg: CONFIG, label } }];

// Nummern einsammeln, deduplizieren, zwei Ausgabeformate bauen.
const cfg   = $('Config').first().json.cfg;
const label = $('Config').first().json.label;

const rows = $input.all().map(i => i.json);
const roh  = rows.map(r => String(r.nummer ?? '').trim()).filter(Boolean);

// Dubletten koennen entstehen, wenn mehrere JTL-Auftraege dieselbe
// Shopify-Nummer tragen (Abo-/Nachlieferungsfaelle).
const einzigartig = [...new Set(roh)];

const liste  = einzigartig.join(cfg.TRENNER);
const zeilen = einzigartig.join('\n');

return [{
  json: {
    label,
    von: cfg.VON,
    bis: cfg.BIS,
    anzahl: einzigartig.length,
    dubletten: roh.length - einzigartig.length,
    zeichen: liste.length,
    // Zum direkten Kopieren aus der n8n-Ausgabe:
    matrixifyFilter: liste
  },
  binary: {}
}, {
  json: { _datei: true, inhalt: liste }
}];

// Zeilenweise Variante als Textdatei. Fuer Matrixify beides nutzbar.
const item  = $input.all().find(i => i.json._datei);
const label = $('Config').first().json.label;
const inhalt = String(item?.json?.inhalt ?? '');

return [{
  json: { dateiname: 'auftragsnummern-' + label + '.txt', zeilen: inhalt ? inhalt.split('\n').length : 0 },
  binary: {
    data: {
      data: Buffer.from(inhalt, 'utf8').toString('base64'),
      mimeType: 'text/plain',
      fileName: 'auftragsnummern-' + label + '.txt',
      fileExtension: 'txt'
    }
  }
}];
